// #af0ff2 קישור הזמנה שבוטל עדיין פעיל — ссылка /accept после отмены / повторного приглашения.
// Кейсы: .qa/tests/invitations/INV-01..INV-04. План: specs/invitations.md.
// Две роли: ADMIN2 (компания B, .qa/auth/admin2.json) приглашает/отменяет, гость (без входа) открывает ссылку.
// Безопасность данных: адреса только qa-auto-inv-…@example.com; пароль не вводится, форма принятия НЕ отправляется;
// в конце каждого теста (finally) все приглашения qa-auto-inv-… отменяются (с подтверждением), в /users остаётся только ADMIN2.
// @data — меняет данные компании B, идёт отдельно, по одному.
import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import { randomBytes } from 'crypto';
import { cancelAllInvites, cancelInviteConfirmed, invite as inviteUser, readBannerLink } from '../helpers/invites';

const NAME = 'QA-AUTO Invite';
const COMPANY_B = 'QA Company B';
const INVALID_TITLE = 'ההזמנה אינה תקפה';
const INVALID_TEXT = 'ההזמנה בוטלה או שאינה תקפה עוד. פנו למנהל החשבון.';
const SUBMIT = 'קבע סיסמה והיכנס';
const RPC = '/rest/v1/rpc/invitation_is_valid';
const SIGNUP = '/auth/v1/signup';

const qaEmail = () => `qa-auto-inv-${Date.now()}-${Math.floor(Math.random() * 1000)}@example.com`;

// Обновлено 15.11.2026 под новое поведение (не баги продукта):
// - ссылка в баннере — только `/accept?token=` без email (#83bf5b), поэтому ссылку берём из баннера сразу после
//   приглашения, а при повторном — ждём новую, отличную от прежней;
// - «ביטול הזמנה» открывает окно подтверждения, отмена — кнопкой «ביטול ההזמנה» (#db7e39).

/** ADMIN2: пригласить email через /users/invite (роль по умолчанию — משתמש רגיל). */
const invite = (admin: Page, email: string) => inviteUser(admin, NAME, email);

/** Ссылка из баннера «…שלחו לו את קישור ההצטרפות (מוצג פעם אחת):»; при повторном приглашении — новая. */
const bannerLink = (admin: Page, previous?: string) => readBannerLink(admin, previous);

/** ADMIN2: «ביטול הזמנה» → подтверждение «ביטול ההזמנה»; строка исчезает. */
const cancelInvite = (admin: Page, email: string) => cancelInviteConfirmed(admin, email);

/** Очистка: отменить все приглашения qa-auto-inv-…; строк qa-auto-inv- не остаётся.
 *  (С 15.11 в компании B постоянный участник «QA Inv14 Member», поэтому пустого состояния больше нет.) */
async function cleanup(admin: Page) {
  await cancelAllInvites(admin, /qa-auto-inv-/);
  await expect(admin.getByText(/qa-auto-inv-/)).toHaveCount(0);
}

/** Гость: считать запросы signUp на странице. */
function watchSignup(guest: Page): string[] {
  const calls: string[] = [];
  guest.on('request', (r) => {
    if (r.url().includes(SIGNUP)) calls.push(r.url());
  });
  return calls;
}

/** Гость открывает ссылку; возвращает ответ RPC invitation_is_valid. */
async function openLink(guest: Page, link: string) {
  const rpc = guest.waitForResponse((r) => r.url().includes(RPC));
  await guest.goto(link);
  return rpc;
}

async function expectInvalid(guest: Page) {
  await expect(guest.getByRole('heading', { name: INVALID_TITLE })).toBeVisible();
  await expect(guest.getByText(INVALID_TEXT, { exact: true })).toBeVisible();
  await expect(guest.getByText('חזרה לכניסה', { exact: true })).toBeVisible();
  await expect(guest.getByLabel(/סיסמה חדשה/)).toHaveCount(0);
  await expect(guest.getByRole('button', { name: SUBMIT })).toHaveCount(0);
}

/** Форма принятия приглашения — только смотрим, НЕ отправляем. */
async function expectForm(guest: Page, email: string) {
  await expect(guest.getByText(/הוזמנת לחשבון של/)).toBeVisible();
  await expect(guest.getByText(COMPANY_B, { exact: true })).toBeVisible();
  const emailField = guest.getByRole('textbox', { name: /אימייל/ });
  await expect(emailField).toHaveValue(email);
  await expect(emailField).not.toBeEditable();
  await expect(guest.getByLabel(/סיסמה חדשה/)).toBeVisible();
  await expect(guest.getByRole('button', { name: SUBMIT })).toBeVisible();
  await expect(guest.getByText(INVALID_TITLE)).toHaveCount(0);
}

test.describe('קישור הזמנה — ביטול והזמנה חוזרת', () => {
  test('הזמנה שבוטלה — הקישור אינו תקף, אין טופס סיסמה ואין signUp #af0ff2 @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    try {
      await invite(admin, email);
      const link = await bannerLink(admin);

      await cancelInvite(admin, email);

      const signups = watchSignup(guest);
      const res = await openLink(guest, link);
      expect(await res.json(), 'invitation_is_valid для отменённого токена').toBe(false);
      await expectInvalid(guest);
      expect(signups, 'по отменённой ссылке не должно быть вызова auth/v1/signup').toEqual([]);
    } finally {
      await cleanup(admin);
    }
  });

  test('הזמנה חוזרת לאותו אימייל — הקישור הישן אינו תקף, החדש מציג טופס #af0ff2 @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    try {
      await invite(admin, email);
      const l1 = await bannerLink(admin);
      await invite(admin, email);
      const l2 = await bannerLink(admin, l1);

      const signups = watchSignup(guest);
      const r1 = await openLink(guest, l1);
      expect(await r1.json(), 'invitation_is_valid для старой ссылки').toBe(false);
      await expectInvalid(guest);

      const r2 = await openLink(guest, l2);
      expect(await r2.json(), 'invitation_is_valid для новой ссылки').toBe(true);
      await expectForm(guest, email);
      expect(signups).toEqual([]);
    } finally {
      await cleanup(admin);
    }
  });

  test('קישור הזמנה פעיל מציג טופס קביעת סיסמה (בקרה) #af0ff2 @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin2');
    const guest = await asUser('guest');
    const email = qaEmail();
    try {
      await invite(admin, email);
      const link = await bannerLink(admin);

      const res = await openLink(guest, link);
      expect(await res.json(), 'invitation_is_valid для действующей ссылки').toBe(true);
      await expectForm(guest, email);
    } finally {
      await cleanup(admin);
    }
  });
});

test.describe('קישור הזמנה פגום — אורח', () => {
  const links = [
    {
      label: 'טוקן אקראי עם פרטי הזמנה בכתובת',
      url: () =>
        `/accept?token=${randomBytes(32).toString('hex')}&email=${encodeURIComponent(qaEmail())}` +
        `&name=QA-AUTO&company=${encodeURIComponent(COMPANY_B).replace(/%20/g, '+')}&inviter=`,
    },
    { label: 'טוקן קצר ושגוי', url: () => '/accept?token=abc' },
  ];
  for (const l of links) {
    test(`${l.label} — "ההזמנה אינה תקפה", בלי טופס #af0ff2 @desktop @prod-safe`, async ({ asUser }) => {
      const guest = await asUser('guest');
      const signups = watchSignup(guest);
      await guest.goto(l.url());
      await expectInvalid(guest);
      expect(signups).toEqual([]);
    });
  }
});
